local M = {}

-- Firenvim: this nvim rendered inside Firefox text fields. Firefox starts
-- `nvim --headless -c 'call firenvim#run()'` through a native-messaging
-- host, so the plugin must be on the runtimepath at startup; lazy loading
-- would miss it. The Firefox side (addon + host manifest) is generated by
-- the firefox module in MainBoard.
M.lz_specs = {
	{
		"firenvim",
		build = { useNixpkgs = "firenvim" },
		lazy = false,
		after = function()
			-- Never grab a field on click; the browser-side shortcut summons
			-- it, :w writes back, :q leaves. The shortcut is set per profile
			-- in about:addons: Firenvim's default Ctrl+E is a Cocoa editing
			-- key on macOS, so it never fires inside a focused field.
			vim.g.firenvim_config = {
				localSettings = { [".*"] = { takeover = "never" } },
			}
			if vim.g.started_by_firenvim then
				vim.o.laststatus = 0
				vim.o.showtabline = 0
			end
		end,
	},
}

return M
